// spec: specs/orders.md §6 · кейсы .qa/tests/orders/ord-16-edit-qty-validation.md, ord-17-edit-price-line.md,
//       ord-18-reedit-after-save.md, ord-19-edit-log-editor-name.md
// seed: tests/seed.admin.spec.ts
// #47ba10 (עבר QA 21.10): «עריכת הזמנה» — ручной ввод кол-ва; 1.5 / 1,5 / 0 / −1 / 99999999999 → сообщение у строки, ничего не
//   сохраняется (после обновления кол-во прежнее); 2 — сохраняется; цена строки меняется вручную («מחיר במחירון: ₪X · המחיר שונה
//   להזמנה זו בלבד», «חזרה למחיר המחירון»), сумма = цена × кол-во.
// #634a4e: «עריכה» сразу после «שמור שינויים» (без обновления) показывает сохранённые кол-во и цену.
// #ef8f45: «תיעוד עריכה» после обновления и повторного открытия — «test admin», не «משתמש לא ידוע».
// Кол-во сверх остатка блокируется в UI (#6a98bd) и на сервере (#929aa5) — здесь кол-во всегда в пределах остатка (10).
// Данные: свой товар QA-AUTO-47ba-<ts> (₪5, остаток 10 «ללא מקום») + заказ клиента test «QA-AUTO-47ba-<ts>».
// afterAll: заказ отклоняется, товар удаляется. Корзина buyer общая → @orders, serial, не параллельно с cart-checkout/order-lifecycle.
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, cleanup, header } from './_qa-order';

test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-47ba-${TS}`;
let orderNo: string | undefined;
let productCreated = false;

const qtyField = (page: Page) => page.getByRole('textbox', { name: `כמות — ${P}`, exact: true });
const priceField = (page: Page) => page.getByRole('spinbutton', { name: `מחיר יחידה — ${P}`, exact: true });
const total = (page: Page) => page.getByText('סה"כ לתשלום').locator('..');
/** Строка товара в карточке заказа: «<שם> — <כמות> ₪<מחיר> ₪<סה"כ>». */
const cardRow = (page: Page) => page.getByText(P, { exact: true }).first().locator('..');
const rowText = (qty: number, price: number) =>
  new RegExp(`—\\s*${qty}\\s*₪${price.toFixed(2).replace('.', '\\.')}\\s*₪${(qty * price).toFixed(2).replace('.', '\\.')}`);

async function openEdit(page: Page) {
  await page.getByRole('button', { name: 'עריכה', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await expect(qtyField(page)).toBeVisible();
}

async function saveAndBackToCard(page: Page) {
  await page.getByRole('button', { name: 'שמור שינויים' }).click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
}

test.describe('orders — עריכת הזמנה: כמות ידנית, מחיר בשורה, עריכה חוזרת, תיעוד עריכה (QA-AUTO)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    productCreated = true;
    const id = await createStockedProduct(page, P, `QA47BA${TS}`, 5, 10);
    await ctx.close();
    orderNo = await buyerPlaceOrder(browser, [{ id, name: P, qty: 1 }], `QA-AUTO-47ba-${TS}`);
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [orderNo], productCreated ? [P] : []);
  });

  test('כמות לא תקינה (1.5, 1,5, 0, −1, 99999999999): הודעה, לא נשמר — אחרי רענון הכמות הקודמת #47ba10 @desktop @orders @data', async ({ page }) => {
    await openOrder(page, orderNo!);
    await expect(header(page)).toContainText('ממתינה לאישור');
    await expect(cardRow(page)).toHaveText(rowText(1, 5));
    await openEdit(page);

    // любая запись (не GET) в Supabase во время невалидных попыток — провал: ничего не должно сохраняться
    const writes: string[] = [];
    const onReq = (r: import('@playwright/test').Request) => {
      if (/supabase\.co\/(rest|functions)\//.test(r.url()) && r.method() !== 'GET' && !/\/rpc\/(search|get|list)/.test(r.url())) writes.push(`${r.method()} ${r.url()}`);
    };
    page.on('request', onReq);
    const CASES: [string, string][] = [
      ['1.5', 'כמות — מספר שלם בלבד'],
      ['1,5', 'כמות — מספר שלם בלבד'],
      ['0', 'הכמות המינימלית היא 1'],
      ['-1', 'כמות — מספר שלם בלבד'],
      ['99999999999', 'זה נראה כמו ברקוד, לא כמות'],
    ];
    for (const [value, message] of CASES) {
      await qtyField(page).fill(value);
      await qtyField(page).press('Tab');
      await expect(page.getByText(message, { exact: true }), `сообщение для «${value}»`).toBeVisible();
      await expect(qtyField(page), `«${value}» не превращается молча в другое число`).toHaveValue(value);
      await expect(total(page), `итог не пересчитан из «${value}»`).toContainText('₪5.00');
      await page.getByRole('button', { name: 'שמור שינויים' }).click();
      await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${orderNo}` })).toBeVisible();
      await expect(page.getByText(message, { exact: true })).toBeVisible();
    }
    page.off('request', onReq);
    expect(writes, 'нет запросов на сохранение').toEqual([]);

    await page.getByRole('button', { name: 'ביטול', exact: true }).click();
    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 30_000 });
    await expect(cardRow(page)).toHaveText(rowText(1, 5));
    await expect(total(page)).toContainText('₪5.00');
  });

  test('כמות 2 + מחיר ידני 7: «מחיר במחירון: ₪5.00 · …», «חזרה למחיר המחירון», נשמר בהזמנה גם אחרי רענון #47ba10 @desktop @orders @data', async ({ page }) => {
    await openOrder(page, orderNo!);
    await openEdit(page);
    await qtyField(page).fill('2');
    await qtyField(page).press('Tab');
    await expect(total(page)).toContainText('₪10.00');

    await priceField(page).fill('7');
    await priceField(page).press('Tab');
    const note = page.getByText('מחיר במחירון: ₪5.00 · המחיר שונה להזמנה זו בלבד', { exact: true });
    await expect(note).toBeVisible();
    await expect(total(page)).toContainText('₪14.00');

    await page.getByRole('button', { name: 'חזרה למחיר המחירון' }).click();
    await expect(priceField(page)).toHaveValue('5');
    await expect(note).toHaveCount(0);
    await expect(total(page)).toContainText('₪10.00');

    await priceField(page).fill('7');
    await priceField(page).press('Tab');
    await expect(total(page)).toContainText('₪14.00');
    await saveAndBackToCard(page);
    await expect(cardRow(page)).toHaveText(rowText(2, 7), { timeout: 15_000 });
    await expect(total(page)).toContainText('₪14.00');

    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 30_000 });
    await expect(cardRow(page)).toHaveText(rowText(2, 7));
    await expect(total(page)).toContainText('₪14.00');
  });

  test('«עריכה» מיד אחרי «שמור שינויים» (בלי רענון) מציגה את הכמות והמחיר שנשמרו #634a4e @desktop @orders @data', async ({ page }) => {
    await openOrder(page, orderNo!);
    await openEdit(page);
    await expect(qtyField(page)).toHaveValue('2');
    await expect(priceField(page)).toHaveValue('7');
    await qtyField(page).fill('3');
    await priceField(page).fill('6');
    await priceField(page).press('Tab');
    await expect(total(page)).toContainText('₪18.00');
    await saveAndBackToCard(page);
    // сразу, без ожидания обновления карточки и без перезагрузки
    await openEdit(page);
    await expect(qtyField(page)).toHaveValue('3');
    await expect(priceField(page)).toHaveValue('6');
    await expect(total(page)).toContainText('₪18.00');
    await page.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page)).toHaveText(rowText(3, 6), { timeout: 15_000 });
  });

  test('«תיעוד עריכה» אחרי רענון ואחרי פתיחה מחדש מהרשימה — «test admin», לא «משתמש לא ידוע» #ef8f45 @desktop @orders @data', async ({ page }) => {
    const log = /^ההזמנה נערכה בידי test admin בתאריך \d{2}\.\d{2}\.\d{4}, \d{2}:\d{2}$/;
    await openOrder(page, orderNo!);
    await page.reload();
    await expect(page.getByRole('heading', { name: 'תיעוד עריכה' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(log)).toBeVisible();
    await expect(page.getByText(/משתמש לא ידוע/)).toHaveCount(0);

    await openOrder(page, orderNo!); // повторное открытие из /orders
    await expect(page.getByRole('heading', { name: 'תיעוד עריכה' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(log)).toBeVisible();
    await expect(page.getByText(/משתמש לא ידוע/)).toHaveCount(0);
  });
});
